sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.aes-page-header {
  width: 100%;
  margin: 0;
  border-radius: 0;
  background-position: center;
  background-repeat: no-repeat;
  background-size: cover;
  padding: $aes-space-3xl;

}

.aes-page-header__content {
  max-width: 760px;
  padding: $aes-space-3xl;
}

.aes-page-header__title {
  margin: 0 0 $aes-space-sm;
  color: $aes-header-text-color;
  font-size: $font-size-h1;
  font-weight: 600;
  line-height: $headings-line-height;
}

.aes-page-header__subtitle {
  margin: 0 0 $aes-space-xl;
  color: $aes-header-secondary-text-color;
  font-size: $font-size-base;
  line-height: $line-height-base;
}

.aes-page-header__search {
  position: relative;
  width: 100%;
  max-width: 620px;
}

.aes-page-header__search-icon {
  position: absolute;
  top: 50%;
  left: 16px;
  z-index: 2;

  color: $text-tertiary;
  font-size: 16px;

  transform: translateY(-50%);
  pointer-events: none;
}

.aes-page-header__search-input {
  width: 100%;
  height: 44px;

  padding-top: 10px;
  padding-right: 16px;
  padding-bottom: 10px;
  padding-left: 44px;

  color: $input-color;
  background-color: $input-bg;
  border: 1px solid $input-border;
  border-radius: $aes-radius-sm;
}

sp_widget.option_schema:
[
  {
    "name": "title",
    "section": "Content",
    "label": "Title",
    "type": "string",
    "default_value": "Announcements"
  },
  {
    "name": "subtitle",
    "section": "Content",
    "label": "Subtitle",
    "type": "string",
    "default_value": "Stay informed about what's happening across your organization."
  },
  {
    "name": "search_placeholder",
    "section": "Content",
    "label": "Search placeholder",
    "type": "string",
    "default_value": "Search announcements"
  },
  {
    "name": "background_image",
    "section": "Content",
    "label": "Background image",
    "type": "string",
    "default_value": "x_733168_aes.announcements_banner.png"
  }
]
